// @generated by:gauntlet run:godseye-local-database
import { mkdir, writeFile } from "node:fs/promises";
import pg from "pg";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { inspectPostgres } from "../packages/core/src/database-postgres.js";
import {
  createPgLaboratory,
  type PgLabCell,
  type PgLaboratory,
  withRuntime,
} from "./pg-lab-fixture.js";

describe("T-AC-34 explicit independent native PostgreSQL laboratory", () => {
  let lab: PgLaboratory;
  let aDev: PgLabCell;
  let aProd: PgLabCell;
  let bDev: PgLabCell;
  const checks: string[] = [];
  const expectedChecks = [
    "production-policy-and-independent-system-identities",
    "development-production-and-cross-project-authentication-denied",
    "tls-required-verify-full-and-private-unix-admin",
    "runtime-dml-without-ddl-role-escalation-or-program-authority",
    "auth-reader-workflow-least-privilege",
    "actual-role-connection-ceiling",
    "actual-restart-persistence-with-cross-cell-data-isolation",
    "existing-reader-write-acl-drift-denied",
    "future-reader-write-acl-drift-denied",
    "column-reader-write-acl-drift-denied",
  ];
  beforeAll(async () => {
    lab = await createPgLaboratory();
    [aDev, aProd, bDev] = lab.cells as [PgLabCell, PgLabCell, PgLabCell];
    for (const cell of lab.cells) {
      await withRuntime(cell, "migration", async (connection) => {
        await connection.query(
          "CREATE TABLE app.items(id integer PRIMARY KEY, value text NOT NULL)",
        );
        await connection.query("CREATE TABLE auth.accounts(id integer PRIMARY KEY)");
        await connection.query("CREATE TABLE analysis.sanitized(id integer PRIMARY KEY)");
        await connection.query("INSERT INTO analysis.sanitized VALUES (1)");
        await connection.query(
          "CREATE FUNCTION app.private_function() RETURNS integer LANGUAGE sql AS 'SELECT 1'",
        );
      });
      await withRuntime(cell, "workflowMigration", (connection) =>
        connection.query("CREATE TABLE workflow.jobs(id integer PRIMARY KEY)"),
      );
    }
  });
  afterAll(async () => {
    if (!lab) return;
    await lab.cleanup();
    const report = {
      run: "godseye-local-database",
      generatedAt: new Date().toISOString(),
      status:
        checks.length === expectedChecks.length &&
        expectedChecks.every((check) => checks.includes(check))
          ? "passed"
          : "incomplete-or-failed",
      coverage: { line: null, branch: null },
      mutation: { score: null, survivors: [] },
      flaky: lab.restartReadiness.retryableConnectionFailures
        ? [{ scenario: "WSL TLS/role connection after native restart", ...lab.restartReadiness }]
        : [],
      flakinessHistory: "artifacts/test-results/pg-lab-flakiness.json",
      layers_run: ["actual-native-postgresql-18-integration"],
      checks,
      qualification: {
        independentClusters: checks.includes("production-policy-and-independent-system-identities"),
        productionContainment: false,
        dockerNetwork: false,
        vmIsolation: false,
        cpuMemoryDiskHardQuotas: false,
        backupPitr: false,
      },
      provenance: lab.provenance,
      gaps: [
        "Native processes share the WSL host and UID; Docker/VM firewall, hard resource quotas, physical backup/PITR and credential rotation remain unqualified.",
        "Coverage and mutation metrics are not measured by this native qualification run.",
      ],
    };
    await mkdir("artifacts/test-results", { recursive: true });
    await writeFile(
      "artifacts/test-results/pg-lab-report.json",
      `${JSON.stringify(report, null, 2)}\n`,
    );
  });

  it("T-AC-34 T-AC-28 inspects three independent system identities, PGDATA and WAL bindings using production inspection", async () => {
    const inspections = await Promise.all(lab.inspect());
    expect(new Set(inspections.map((item) => item.systemIdentifier)).size).toBe(3);
    expect(new Set(inspections.map((item) => item.dataDirectory)).size).toBe(3);
    expect(new Set(lab.cells.map((cell) => cell.native.wal)).size).toBe(3);
    expect(
      inspections.every(
        (item, index) =>
          item.policyVerified && item.dataDirectory === lab.cells[index]?.native.data,
      ),
    ).toBe(true);
    checks.push("production-policy-and-independent-system-identities");
  });

  it("T-AC-34 T-AC-31 refuses same-project production and cross-project credentials", async () => {
    for (const target of [aProd, bDev]) {
      await expect(target.runtime("api", { password: aDev.material.api })).rejects.toThrow();
      await expect(
        target.runtime("api", { user: aDev.profile.roles.api.name, password: aDev.material.api }),
      ).rejects.toThrow();
      await expect(
        aDev.runtime("api", { database: target.profile.applicationDatabase }),
      ).rejects.toThrow();
    }
    checks.push("development-production-and-cross-project-authentication-denied");
  });

  it("T-AC-34 T-AC-31 requires TLS, verifies server identity and refuses TCP bootstrap administration", async () => {
    await expect(aDev.runtime("api", { servername: "wrong-host.invalid" })).rejects.toThrow();
    await expect(aDev.runtime("api", { ca: "" })).rejects.toThrow();
    const unencrypted = new pg.Client({
      host: "127.0.0.1",
      port: aDev.native.port,
      user: aDev.profile.roles.api.name,
      password: aDev.material.api,
      database: aDev.profile.applicationDatabase,
      ssl: false,
      connectionTimeoutMillis: 5000,
    });
    try {
      await expect(unencrypted.connect()).rejects.toThrow();
    } finally {
      await unencrypted.end();
    }
    expect(await lab.adminTcpDenied(0)).toBe(true);
    checks.push("tls-required-verify-full-and-private-unix-admin");
  });

  it("T-AC-34 T-AC-30 permits runtime DML but denies DDL, authorization changes and private functions", async () => {
    await withRuntime(aDev, "api", async (connection) => {
      await connection.query("INSERT INTO app.items VALUES (1,'persisted')");
      expect(
        (await connection.query("SELECT value FROM app.items WHERE id=1")).rows[0]?.value,
      ).toBe("persisted");
      for (const sql of [
        "CREATE TABLE app.forbidden(id integer)",
        "CREATE TEMP TABLE forbidden(id integer)",
        "CREATE SCHEMA forbidden",
        "ALTER TABLE app.items ADD COLUMN forbidden integer",
        "CREATE ROLE forbidden",
        `SET ROLE "${aDev.profile.roles.migration.name}"`,
        "SELECT app.private_function()",
        "COPY app.items TO PROGRAM 'true'",
      ]) {
        await expect(connection.query(sql)).rejects.toThrow();
      }
    });
    checks.push("runtime-dml-without-ddl-role-escalation-or-program-authority");
  });

  it("T-AC-34 T-AC-30 separates auth, sanitized reader and workflow authority", async () => {
    await withRuntime(aDev, "auth", async (connection) => {
      await connection.query("INSERT INTO auth.accounts VALUES (1)");
      await expect(connection.query("SELECT * FROM app.items")).rejects.toThrow();
    });
    await withRuntime(aDev, "reader", async (connection) => {
      expect((await connection.query("SELECT id FROM analysis.sanitized")).rows).toEqual([
        { id: 1 },
      ]);
      await expect(connection.query("INSERT INTO analysis.sanitized VALUES (2)")).rejects.toThrow();
      await expect(connection.query("SELECT * FROM auth.accounts")).rejects.toThrow();
      await expect(connection.query("SELECT * FROM app.items")).rejects.toThrow();
    });
    await withRuntime(aDev, "workflow", (connection) =>
      connection.query("INSERT INTO workflow.jobs VALUES (1)"),
    );
    await expect(
      aDev.runtime("workflow", { database: aDev.profile.applicationDatabase }),
    ).rejects.toThrow();
    await expect(
      aDev.runtime("api", { database: aDev.profile.workflowDatabase }),
    ).rejects.toThrow();
    checks.push("auth-reader-workflow-least-privilege");
  });

  it("T-AC-34 T-AC-28 enforces a finite role connection ceiling", async () => {
    const connections = await Promise.all(
      Array.from({ length: aDev.profile.roles.api.connections }, () => aDev.runtime("api")),
    );
    try {
      await expect(aDev.runtime("api")).rejects.toThrow();
    } finally {
      await Promise.all(connections.map((connection) => connection.end()));
    }
    checks.push("actual-role-connection-ceiling");
  });

  it("T-AC-34 T-AC-32 retains identity, policy and application data after a real PostgreSQL restart", async () => {
    const before = await Promise.all(lab.inspect());
    await lab.restart(0);
    const after = await Promise.all(lab.inspect());
    expect(after.map((item) => item.systemIdentifier)).toEqual(
      before.map((item) => item.systemIdentifier),
    );
    await withRuntime(aDev, "worker", async (connection) => {
      expect(
        (await connection.query("SELECT value FROM app.items WHERE id=1")).rows[0]?.value,
      ).toBe("persisted");
    });
    for (const cell of [aProd, bDev])
      await withRuntime(cell, "api", async (connection) => {
        expect(
          (await connection.query("SELECT count(*)::int AS count FROM app.items")).rows[0]?.count,
        ).toBe(0);
      });
    checks.push("actual-restart-persistence-with-cross-cell-data-isolation");
  });

  it.each([
    ["existing", "GRANT INSERT ON analysis.sanitized", "REVOKE INSERT ON analysis.sanitized"],
    ["column", "GRANT INSERT(id) ON analysis.sanitized", "REVOKE INSERT(id) ON analysis.sanitized"],
  ] as const)(
    "T-AC-30 T-AC-34 rejects effective %s reader write ACL drift in production inspection",
    async (kind, grant, revoke) => {
      const admin = await aProd.admin(aProd.profile.applicationDatabase);
      const reader = `"${aProd.profile.roles.reader.name}"`;
      try {
        await admin.query(`${grant} TO ${reader}`);
        await withRuntime(aProd, "reader", (connection) =>
          connection.query("INSERT INTO analysis.sanitized(id) VALUES (42)"),
        );
        await expect(inspectPostgres(aProd.profile, aProd.admin)).rejects.toThrow(
          "Effective PostgreSQL policy inspection failed",
        );
      } finally {
        await admin.query(`${revoke} FROM ${reader}`);
        await admin.query("DELETE FROM analysis.sanitized WHERE id=42");
        await admin.end();
      }
      expect((await inspectPostgres(aProd.profile, aProd.admin)).policyVerified).toBe(true);
      checks.push(`${kind}-reader-write-acl-drift-denied`);
    },
  );

  it("T-AC-30 T-AC-34 rejects future reader write ACL drift before creating a vulnerable table", async () => {
    const admin = await aProd.admin(aProd.profile.applicationDatabase);
    const prefix = `ALTER DEFAULT PRIVILEGES FOR ROLE "${aProd.profile.roles.migration.name}" IN SCHEMA analysis`;
    const reader = `"${aProd.profile.roles.reader.name}"`;
    try {
      await admin.query(`${prefix} GRANT INSERT ON TABLES TO ${reader}`);
      await expect(inspectPostgres(aProd.profile, aProd.admin)).rejects.toThrow(
        "Effective PostgreSQL policy inspection failed",
      );
    } finally {
      await admin.query(`${prefix} REVOKE INSERT ON TABLES FROM ${reader}`);
      await admin.end();
    }
    expect((await inspectPostgres(aProd.profile, aProd.admin)).policyVerified).toBe(true);
    checks.push("future-reader-write-acl-drift-denied");
  });
});
